79	    /// Fails with an error if the length has a non-zero font-relative part.
80	    fn ensure_that_em_is_zero(&self, span: Span, unit: &str) -> SourceResult<()> {
81	        if self.em == Em::zero() {
82	            return Ok(());
83	        }
