```rust
// src/layout/rel.rs
impl<T: NumericLength> Add for Rel<T> {
    type Output = Self;

    fn add(self, other: Self) -> Self::Output {
        Self { rel: self.rel + other.rel, abs: self.abs + other.abs }
    }
}
```
