impl<T> Resolve for Rel<T>
where
    T: Resolve + NumericLength,
    <T as Resolve>::Output: NumericLength,
{
    type Output = Rel<<T as Resolve>::Output>;

    fn resolve(self, styles: StyleChain) -> Self::Output {
        self.map(|abs| abs.resolve(styles))
